3|import static com.oms.process.ProcessConstants.ERR_INVALID_ORDER;
4|import static com.oms.process.ProcessConstants.JOB_VALIDATE_ORDER;
5|import static com.oms.process.ProcessConstants.VAR_CORRECTION_ITEMS;
6|import static com.oms.process.ProcessConstants.VAR_ORDER;
7|
8|import com.fasterxml.jackson.core.type.TypeReference;
9|import com.fasterxml.jackson.databind.ObjectMapper;
10|import com.oms.model.OrderInput;
11|import com.oms.model.OrderItem;
12|import io.camunda.zeebe.client.api.response.ActivatedJob;
13|import io.camunda.zeebe.client.api.worker.JobClient;
14|import io.camunda.zeebe.spring.client.annotation.JobWorker;
15|import java.util.HashMap;
16|import java.util.List;
17|import java.util.Map;
18|import org.slf4j.Logger;
19|import org.slf4j.LoggerFactory;
20|import org.springframework.stereotype.Component;
21|
22|/**
23| * Commerce-platform worker — the Camunda equivalent of the Temporal
24| * {@code ValidateOrderAPI} activity, which ran on a dedicated {@code
25| * COMMERCE_QUEUE} capped at 150 RPS.
26| *
27| * <p>Zeebe has no per-task-queue rate limiter like Temporal's {@code
28| * TaskQueueActivitiesPerSecond}. The closest lever is bounding how many jobs a
29| * worker activates concurrently ({@code maxJobsActive}) and running a fixed
30| * number of replicas; a true RPS cap would need a rate-limiting gateway in
31| * {@code validateOrder} itself. This is called out in the README's mapping
32| * table as the one behavioural gap versus Temporal.
33| *
34| * <p>Business validation failures are surfaced as the BPMN error {@code
35| * INVALID_ORDER}, caught by the boundary event that drives the correction loop
36| * — mirroring the Temporal NonRetryable {@code ValidationFailure} that parked
37| * the workflow in {@code AWAITING_CORRECTION}.
38| */
39|@Component
40|public class CommerceWorkers {
41|
42|  private static final Logger LOG = LoggerFactory.getLogger(CommerceWorkers.class);
43|
44|  private final ObjectMapper objectMapper;
45|
46|  public CommerceWorkers(ObjectMapper objectMapper) {
47|    this.objectMapper = objectMapper;
48|  }
49|
50|  @JobWorker(type = JOB_VALIDATE_ORDER, autoComplete = false, maxJobsActive = 150)
51|  public void validateOrder(JobClient client, ActivatedJob job) {
52|    Map<String, Object> vars = job.getVariablesAsMap();
53|    OrderInput order = objectMapper.convertValue(vars.get(VAR_ORDER), OrderInput.class);
54|
55|    // Apply any pending SupportCorrection (delivered as correctionItems) before
56|    // re-validating — the parity of WorkflowState.ApplyCorrection.
57|    order = applyCorrection(order, vars.get(VAR_CORRECTION_ITEMS));
58|
59|    LOG.info("validate-order started orderId={}", order == null ? null : order.orderId());
60|
61|    String rejection = validationError(order);
62|    if (rejection != null) {
63|      LOG.warn("Order validation failed: {}", rejection);
64|      // Non-retryable business failure -> correction loop (not a job retry).
65|      client
66|          .newThrowErrorCommand(job)
67|          .errorCode(ERR_INVALID_ORDER)
68|          .errorMessage(rejection)
69|          .send()
70|          .join();
71|      return;
72|    }
73|
74|    // Mock commerce validation is idempotent; echo the (validated) order back
75|    // and clear the consumed correction.
76|    LOG.info("validate-order completed orderId={}", order.orderId());
77|    Map<String, Object> out = new HashMap<>();
78|    out.put(VAR_ORDER, order);
79|    out.put(VAR_CORRECTION_ITEMS, null);
80|    client.newCompleteCommand(job).variables(out).send().join();
81|  }
82|
83|  /** Replaces the order's items with corrected ones when a correction is pending. */
84|  private OrderInput applyCorrection(OrderInput order, Object correctionItemsRaw) {
85|    if (order == null || correctionItemsRaw == null) {
86|      return order;
87|    }
88|    List<OrderItem> items =
89|        objectMapper.convertValue(correctionItemsRaw, new TypeReference<List<OrderItem>>() {});
90|    if (items == null || items.isEmpty()) {
91|      return order;
92|    }
93|    return new OrderInput(
94|        order.orderId(), order.customerId(), items, order.totalAmount(), order.currency());
95|  }
96|
97|  /** Returns {@code null} when the order is valid, else the rejection reason. */
98|  private static String validationError(OrderInput order) {
99|    if (order == null || order.orderId() == null || order.orderId().isBlank()) {
100|      return "order_id is required";
101|    }
102|    if (order.items() == null || order.items().isEmpty()) {
103|      return "order must contain at least one item";
104|    }
105|    if (order.totalAmount() <= 0) {
106|      return "invalid total_amount: " + order.totalAmount();
107|    }
108|    if (order.customerId() == null || order.customerId().isBlank()) {
109|      return "customer_id is required";
110|    }
111|    return null;
112|  }
113|}
