3|import static com.oms.process.ProcessConstants.ERR_INVALID_PAYMENT;
4|import static com.oms.process.ProcessConstants.HEADER_STATUS;
5|import static com.oms.process.ProcessConstants.JOB_ENRICH_ORDER;
6|import static com.oms.process.ProcessConstants.JOB_PUBLISH_FULFILLMENT;
7|import static com.oms.process.ProcessConstants.JOB_UPDATE_DASHBOARD;
8|import static com.oms.process.ProcessConstants.JOB_VALIDATE_PAYMENT;
9|import static com.oms.process.ProcessConstants.VAR_ORDER;
10|import static com.oms.process.ProcessConstants.VAR_ORDER_ID;
11|import static com.oms.process.ProcessConstants.VAR_PAYMENT;
12|
13|import com.fasterxml.jackson.databind.ObjectMapper;
14|import com.oms.dashboard.DashboardRepository;
15|import com.oms.dashboard.DashboardStatus;
16|import com.oms.model.FulfillmentMessage;
17|import com.oms.model.OrderInput;
18|import com.oms.model.OrderItem;
19|import com.oms.model.OrderStatus;
20|import com.oms.model.PaymentInput;
21|import io.camunda.zeebe.client.api.response.ActivatedJob;
22|import io.camunda.zeebe.client.api.worker.JobClient;
23|import io.camunda.zeebe.spring.client.annotation.JobWorker;
24|import java.time.Instant;
25|import java.util.ArrayList;
26|import java.util.List;
27|import java.util.Map;
28|import org.slf4j.Logger;
29|import org.slf4j.LoggerFactory;
30|import org.springframework.stereotype.Component;
31|
32|/**
33| * The OMS-queue activities from the Temporal app, re-expressed as Zeebe job
34| * workers: {@code validate-payment}, {@code enrich-order},
35| * {@code update-dashboard} and {@code publish-fulfillment}.
36| *
37| * <p>Every worker is idempotent and safe to re-run, because Zeebe (like
38| * Temporal) delivers jobs at least once.
39| */
40|@Component
41|public class OmsWorkers {
42|
43|  private static final Logger LOG = LoggerFactory.getLogger(OmsWorkers.class);
44|
45|  private final ObjectMapper objectMapper;
46|  private final DashboardRepository dashboardRepo;
47|
48|  public OmsWorkers(ObjectMapper objectMapper, DashboardRepository dashboardRepo) {
49|    this.objectMapper = objectMapper;
50|    this.dashboardRepo = dashboardRepo;
51|  }
52|
53|  // ------------------------------------------------------------------ payment
54|
55|  /**
56|   * Validates the payment RRN and amount. Business failures raise the BPMN error
57|   * {@code INVALID_PAYMENT}, caught by the boundary event that loops back to the
58|   * {@code CapturePayment} wait — the parity of the Temporal payment retry loop
59|   * that cleared the invalid payment and awaited a fresh {@code CapturePayment}
60|   * signal. Transient/system failures instead fall through as job failures and
61|   * are retried up to the task's configured retry count (5).
62|   */
63|  @JobWorker(type = JOB_VALIDATE_PAYMENT, autoComplete = false)
64|  public void validatePayment(JobClient client, ActivatedJob job) {
65|    Map<String, Object> vars = job.getVariablesAsMap();
66|    PaymentInput payment = objectMapper.convertValue(vars.get(VAR_PAYMENT), PaymentInput.class);
67|    OrderInput order = objectMapper.convertValue(vars.get(VAR_ORDER), OrderInput.class);
68|    double expectedAmount = order == null ? 0 : order.totalAmount();
69|
70|    LOG.info("validate-payment started rrn={}", payment == null ? null : payment.rrn());
71|
72|    String rejection = validationError(payment, expectedAmount);
73|    if (rejection != null) {
74|      LOG.warn("Payment validation failed: {}", rejection);
75|      // BPMN error -> boundary event loops back to the CapturePayment wait. No
76|      // need to clear the payment variable: the next CapturePayment message
77|      // overwrites it (mirrors the Temporal loop awaiting a fresh signal).
78|      client
79|          .newThrowErrorCommand(job)
80|          .errorCode(ERR_INVALID_PAYMENT)
81|          .errorMessage(rejection)
82|          .send()
83|          .join();
84|      return;
85|    }
86|
87|    LOG.info("validate-payment completed rrn={}", payment.rrn());
88|    client.newCompleteCommand(job).variables(Map.of(VAR_PAYMENT, payment)).send().join();
89|  }
90|
91|  /** Returns {@code null} when the payment is valid, else the rejection reason. */
92|  private static String validationError(PaymentInput payment, double expectedAmount) {
93|    if (payment == null || payment.rrn() == null || payment.rrn().isEmpty()) {
94|      return "payment RRN is empty";
95|    }
96|    if (payment.rrn().length() != 12) {
97|      return "invalid RRN length " + payment.rrn().length() + "; must be 12 digits";
98|    }
99|    for (int i = 0; i < payment.rrn().length(); i++) {
100|      char c = payment.rrn().charAt(i);
101|      if (c < '0' || c > '9') {
102|        return "RRN must contain only digits";
103|      }
104|    }
105|    if (payment.amount() <= 0) {
106|      return "invalid payment amount: " + payment.amount();
107|    }
108|    // Compare money as integer cents; exact double equality is unsafe for
109|    // amounts that aren't representable in binary floating point.
110|    if (Math.round(payment.amount() * 100) != Math.round(expectedAmount * 100)) {
111|      return String.format(
112|          "payment amount %.2f does not match order total %.2f", payment.amount(), expectedAmount);
113|    }
114|    return null;
115|  }
116|
117|  // ------------------------------------------------------------------- enrich
118|
119|  /**
120|   * Enriches order items with PIM metadata (sku_id, brand_code) and writes the
121|   * enriched {@code order} back. Equivalent to {@code EnrichWithPIM}; safe to
122|   * retry because enrichment is deterministic on the input.
123|   */
124|  @JobWorker(type = JOB_ENRICH_ORDER)
125|  public Map<String, Object> enrichOrder(ActivatedJob job) {
126|    OrderInput order =
127|        objectMapper.convertValue(job.getVariablesAsMap().get(VAR_ORDER), OrderInput.class);
128|    LOG.info("enrich-order started orderId={}", order.orderId());
129|
130|    List<OrderItem> enriched = new ArrayList<>();
131|    List<OrderItem> items = order.items() == null ? List.of() : order.items();
132|    for (int i = 0; i < items.size(); i++) {
133|      OrderItem item = items.get(i);
134|      String sku =
135|          item.skuId() == null || item.skuId().isBlank()
136|              ? "SKU-" + order.orderId() + "-" + (i + 1)
137|              : item.skuId();
138|      String brand =
139|          item.brandCode() == null || item.brandCode().isBlank()
140|              ? "BRAND-" + item.itemId()
141|              : item.brandCode();
142|      enriched.add(
143|          new OrderItem(item.itemId(), item.quantity(), item.unitPrice(), sku, brand));
144|    }
145|
146|    OrderInput enrichedOrder =
147|        new OrderInput(
148|            order.orderId(),
149|            order.customerId(),
150|            enriched,
151|            order.totalAmount(),
152|            order.currency());
153|    LOG.info("enrich-order completed orderId={} itemCount={}", order.orderId(), enriched.size());
154|    return Map.of(VAR_ORDER, enrichedOrder);
155|  }
156|
157|  // ---------------------------------------------------------------- dashboard
158|
159|  /**
160|   * Upserts the customer dashboard read model. The target status is carried on
161|   * the service task's {@code status} job header, so a single worker serves
162|   * every dashboard step in the model.
163|   *
164|   * <p>As in the Temporal app, this update is best-effort/non-fatal: a
165|   * projection write failure is logged and the job still completes so it can
166|   * never abort the order. (Temporal warned and continued; here we complete the
167|   * job rather than let it incident.)
168|   */
169|  @JobWorker(type = JOB_UPDATE_DASHBOARD)
170|  public void updateDashboard(ActivatedJob job) {
171|    String orderId = String.valueOf(job.getVariablesAsMap().get(VAR_ORDER_ID));
172|    String statusHeader = job.getCustomHeaders().get(HEADER_STATUS);
173|
174|    OrderStatus status;
175|    try {
176|      status = OrderStatus.fromString(statusHeader);
177|    } catch (RuntimeException e) {
178|      // Matches ValidationFailure on an unsupported dashboard status.
179|      LOG.error("Unsupported dashboard status header: {}", statusHeader);
180|      throw e;
181|    }
182|
183|    LOG.info("update-dashboard orderId={} status={}", orderId, status);
184|    try {
185|      dashboardRepo.upsert(new DashboardStatus(orderId, status.name(), Instant.now()));
186|    } catch (RuntimeException e) {
187|      LOG.warn("dashboard update failed; continuing orderId={} status={}", orderId, status, e);
188|    }
189|  }
190|
191|  // -------------------------------------------------------------- fulfillment
192|
193|  /**
194|   * Publishes the fulfillment message. Equivalent to {@code
195|   * PublishToFulfillment}; consumers deduplicate on {@code eventId}. Mocked as a
196|   * log line here, exactly like the Temporal activity.
197|   */
198|  @JobWorker(type = JOB_PUBLISH_FULFILLMENT)
199|  public void publishToFulfillment(ActivatedJob job) {
200|    Map<String, Object> vars = job.getVariablesAsMap();
201|    OrderInput order = objectMapper.convertValue(vars.get(VAR_ORDER), OrderInput.class);
202|    PaymentInput payment = objectMapper.convertValue(vars.get(VAR_PAYMENT), PaymentInput.class);
203|
204|    FulfillmentMessage msg =
205|        new FulfillmentMessage(
206|            "fulfillment:" + order.orderId() + ":v1",
207|            1,
208|            order.customerId(),
209|            order.orderId(),
210|            payment,
211|            order.items());
212|
213|    LOG.info(
214|        "publish-fulfillment: published to order-fulfillment topic eventId={} orderId={} customerId={} itemCount={} paymentRRN={}",
215|        msg.eventId(),
216|        msg.orderId(),
217|        msg.customerId(),
218|        msg.items() == null ? 0 : msg.items().size(),
219|        payment == null ? null : payment.rrn());
220|  }
221|}
