	}

	if validationAttempt != 2 {
		t.Errorf("expected 2 validation attempts, got %d", validationAttempt)
	}

	env.AssertExpectations(t)
}

func TestOrderProcessingWorkflow_InvalidPayment_Retry(t *testing.T) {
	testSuite := &testsuite.WorkflowTestSuite{}
	env := testSuite.NewTestWorkflowEnvironment()

	// Track payment validation attempts
	paymentAttempt := 0

	env.OnActivity(activities.UpdateDashboard, func(ctx interface{}, in shared.UpdateDashboardInput) (shared.UpdateDashboardOutput, error) {
		return shared.UpdateDashboardOutput{}, nil
	})

	env.OnActivity(activities.ValidateOrder, func(ctx interface{}, in shared.ValidateOrderInput) (shared.ValidateOrderOutput, error) {
		return shared.ValidateOrderOutput{Order: in.Order}, nil
	})

	env.OnActivity(activities.ValidatePayment, func(ctx interface{}, in shared.ValidatePaymentInput) (shared.ValidatePaymentOutput, error) {
		paymentAttempt++
		if paymentAttempt == 1 {
			// First attempt fails
			return shared.ValidatePaymentOutput{}, temporal.NewNonRetryableApplicationError(
				"payment amount 50.00 does not match order total 100.00",
				"INVALID_PAYMENT",
				nil,
			)
		}
		// Second attempt succeeds
		return shared.ValidatePaymentOutput{Payment: in.Payment}, nil
	})

	env.OnActivity(activities.EnrichOrder, func(ctx interface{}, in shared.EnrichOrderInput) (shared.EnrichOrderOutput, error) {
		return shared.EnrichOrderOutput{Order: in.Order}, nil
	})

	env.OnActivity(activities.PublishFulfillment, func(ctx interface{}, in shared.PublishFulfillmentInput) (shared.PublishFulfillmentOutput, error) {
		return shared.PublishFulfillmentOutput{}, nil
	})

	// Send first payment signal (invalid) after 1 second
	env.RegisterDelayedCallback(func() {
		env.SignalWorkflow("Message_CapturePayment", shared.CapturePaymentSignal{
			Payment: shared.PaymentInput{
				RRN:           "123456789012",
				Amount:        50.0, // Wrong amount
				Currency:      "USD",
				PaymentMethod: "CARD",
				PaidAt:        "2024-01-01T10:00:00Z",
			},
		})
	}, 1*time.Second)

	// Send second payment signal (valid) after 2 seconds
	env.RegisterDelayedCallback(func() {
		env.SignalWorkflow("Message_CapturePayment", shared.CapturePaymentSignal{
			Payment: shared.PaymentInput{
				RRN:           "999999999999",
				Amount:        100.0, // Correct amount
				Currency:      "USD",
				PaymentMethod: "CARD",
				PaidAt:        "2024-01-01T11:00:00Z",
			},
		})
	}, 2*time.Second)

	// Execute workflow
	env.ExecuteWorkflow(OrderProcessingWorkflow, shared.OrderProcessingInput{
		OrderID:    "order-123",
		CustomerID: "customer-456",
		Items: []shared.OrderItem{
			{ItemID: "item-1", Quantity: 2, UnitPrice: 50.0},
		},
		TotalAmount: 100.0,
		Currency:    "USD",
	})

	if !env.IsWorkflowCompleted() {
		t.Fatal("workflow did not complete")
	}

	if err := env.GetWorkflowError(); err != nil {
		t.Fatalf("workflow returned error: %v", err)
	}

	var result shared.OrderProcessingResult
	if err := env.GetWorkflowResult(&result); err != nil {
		t.Fatalf("failed to get workflow result: %v", err)
	}

	if result.Status != "FULFILLED" {
		t.Errorf("expected status FULFILLED, got %s", result.Status)
	}

	if paymentAttempt != 2 {
		t.Errorf("expected 2 payment attempts, got %d", paymentAttempt)
	}

	env.AssertExpectations(t)
}

